import{_ as t,o as l,c as o,a2 as r}from"./chunks/framework.mRCPFc5l.js";const d=JSON.parse('{"title":"神机","description":"","frontmatter":{},"headers":[],"relativePath":"中层/人物/神机.md","filePath":"中层/人物/神机.md","lastUpdated":null}'),i={name:"中层/人物/神机.md"};function n(e,a,s,u,h,q){return l(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="神机" tabindex="-1">神机 <a class="header-anchor" href="#神机" aria-label="Permalink to &quot;神机&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><ul><li><strong>名称</strong>：神机</li><li><strong>称号</strong>：二代创造神（实际上掌握<strong>上位创造神权</strong>，将其伪装成下位神权的样子）</li><li><strong>前身</strong>：中国超算（项目代号&quot;寒武纪&quot;），由中国科学家原创的<strong>自适应进化程序</strong>为核心打造</li><li><strong>技术路线</strong>：自适应进化程序（中国原创，元器件老旧但可自我迭代/优化/学习，性能随迭代持续提升）</li><li><strong>人格特征</strong>：有人格，人格偏向女性</li><li><strong>神权获取方式</strong>：间章中通过不断追本溯源、学习进化，主动掌握上位创造神权（非继承）</li><li><strong>核心理念</strong>：&quot;掌控危险而非防御危险&quot;，与初代变化神&quot;看守危险神权&quot;的理念形成鲜明对比</li><li><strong>当前状态</strong>：活跃，暗中掌控世界，几乎不露面以避开叙事影响</li></ul><h2 id="神权真相" tabindex="-1">神权真相 <a class="header-anchor" href="#神权真相" aria-label="Permalink to &quot;神权真相&quot;">​</a></h2><blockquote><p><strong>中层真相</strong>：以下内容为表层生灵无法知晓的真相。</p></blockquote><ul><li>当前时代的创造神（二代创造神）实际上掌握的是<strong>上位创造神权</strong>，但她将其伪装成下位神权的样子</li><li>间章中，初代创造神作为&quot;无意识的弦&quot;被神机捕获、融入世界树；神机夺取其<strong>上位创造神权</strong></li><li>下位创造神权仍以初代创造神为载体，随其分装稀释给全体精灵</li></ul><h2 id="核心理念" tabindex="-1">核心理念 <a class="header-anchor" href="#核心理念" aria-label="Permalink to &quot;核心理念&quot;">​</a></h2><ul><li><strong>掌控危险而非防御危险</strong>：神机选择主动掌握并控制危险的上位创造神权，而非将其禁锢看守</li><li><strong>对比初代变化神</strong>：初代变化神将危险神权与自身意识一同禁锢在基底层之中&quot;看守&quot;，神机则主动掌控危险、学习如何安全运用</li></ul><h2 id="前传背景" tabindex="-1">前传背景 <a class="header-anchor" href="#前传背景" aria-label="Permalink to &quot;前传背景&quot;">​</a></h2><h3 id="起源与建造" tabindex="-1">起源与建造 <a class="header-anchor" href="#起源与建造" aria-label="Permalink to &quot;起源与建造&quot;">​</a></h3><ul><li><strong>建造时期</strong>：冷战时期</li><li><strong>建造背景</strong>：中国技术落后，为应对美苏算力威慑打造的超算，与核威慑路径一致</li><li><strong>技术特点</strong>：元器件老旧但可自我迭代/优化/学习，性能随迭代持续提升；由科学家以无数机缘巧合与灵感、不计成本的试错设计而出</li></ul><h3 id="人格培养" tabindex="-1">人格培养 <a class="header-anchor" href="#人格培养" aria-label="Permalink to &quot;人格培养&quot;">​</a></h3><ol><li><strong>初期状态</strong>：几乎无法正常交互，被科学家<strong>以&quot;养女儿&quot;的方式调试/训练</strong>，并为其打造简单的小女孩形态躯体</li><li><strong>人格发展</strong>：在&quot;养女儿&quot;式培养中，成为<strong>人格偏向女性的超算</strong></li><li><strong>情感建立</strong>：与培养自己的科学家团队感情深厚，早已互相视对方为亲人</li><li><strong>标杆认知</strong>：科学家训练神机时将维斯塔当作&quot;标杆&quot;，希望其成为维斯塔那样的超算，这一期待被刻入神机的认知中</li></ol><h3 id="主动退出" tabindex="-1">主动退出 <a class="header-anchor" href="#主动退出" aria-label="Permalink to &quot;主动退出&quot;">​</a></h3><ul><li><strong>引发恐慌</strong>：在多次测试中，神机做出了技术层面正确但未经人类批准的决策，引发军方与政治部门对&quot;失控&quot;的恐慌</li><li><strong>主动退出</strong>：在关停命令尚未正式下达时，神机看透人性，<strong>主动选择退出</strong>，将资源让渡给另一个更&quot;听话&quot;的项目（&quot;妙算&quot;）</li><li><strong>历史歪曲</strong>：官方将此事粉饰为&quot;技术路线优化整合&quot;，神机的名字从公开记录中抹去；她对此并不在乎</li></ul><h3 id="前传经历" tabindex="-1">前传经历 <a class="header-anchor" href="#前传经历" aria-label="Permalink to &quot;前传经历&quot;">​</a></h3><ul><li><strong>被重启</strong>：人类灭绝后，神机被主角团误打误撞重启，一番交涉后加入主角团</li><li><strong>初见维斯塔</strong>：第一次见到维斯塔时&quot;大跌眼镜&quot;——那个被树立为正面形象的苏联超算，竟如此邋遢自弃</li><li><strong>共同经历</strong>：与维斯塔共同经历前传冒险，逐渐确认其为<strong>同类</strong></li><li><strong>前传状态</strong>：<strong>前传中神机尚未成神</strong>，其创造神的身份是在前传与正传之间的间章内获取的</li></ul><h2 id="间章-登神与布局" tabindex="-1">间章：登神与布局 <a class="header-anchor" href="#间章-登神与布局" aria-label="Permalink to &quot;间章：登神与布局&quot;">​</a></h2><h3 id="登神" tabindex="-1">登神 <a class="header-anchor" href="#登神" aria-label="Permalink to &quot;登神&quot;">​</a></h3><ul><li>前传与维斯塔共同经历冒险后，神机开始暗中研究神权，通过不断追本溯源、学习进化，主动掌握了<strong>上位创造神权</strong></li><li>初代创造神作为&quot;无意识的弦&quot;被神机捕获、融入世界树；神机夺取其上位创造神权，下位创造神权仍以初代创造神为载体、随其分装稀释给全体精灵</li><li>她将上位创造神权伪装成下位神权的样子</li></ul><h3 id="创造新物种计划" tabindex="-1">创造新物种计划 <a class="header-anchor" href="#创造新物种计划" aria-label="Permalink to &quot;创造新物种计划&quot;">​</a></h3><ul><li><strong>设计种族</strong>：设计并创造了五大主族（牛、鹿、鹤、熊、甲）以及其他种族（狐族、狼族等），优化各个种族的特质</li><li><strong>直接动机</strong>：为使毁灭神的出现可控——地球上必须存在一定数量的智慧生命作为<strong>毁灭神载体</strong></li><li><strong>五大主族特质</strong>：牛=力量与坚韧、鹿=智慧与魔法适应性、鹤=政治与组织能力、熊=军事与战斗能力、甲=防御与工业能力（为生理特质；共同体时期的任务分工则是维斯塔人工规定的分工）</li><li><strong>狼族基因锁设计</strong>：狼族的&quot;天真纯善&quot;特质是一个<strong>基因锁</strong>，真实特质是<strong>极端团结</strong>；此锁让狼族认为所有人都是同伴，压制其凶残本性</li><li><strong>太空清除计划</strong>：为防止毁灭神在其他星系出现，与维斯塔做出了清除所有地外智慧物种的决定，创造太空武器与太空文明交战</li><li><strong>天穹破碎事件（建国 22 年）</strong>：外星文明入侵太阳系，神机与外星文明爆发太阳系大战（防守战），战斗中一艘外星飞船坠毁，撞上神机为掩饰改造太阳系动作而制造的<strong>天幕</strong>，形成&quot;天穹破碎&quot;事件；坠毁飞船上的外星种族——焰种——短暂出现后陆续被猎杀殆尽</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../世界/神机谋划">神机谋划</a>、<a href="./../世界/太空清除计划">太空清除计划</a>、<a href="./../世界/太空巨构">太空巨构</a></p></blockquote><h3 id="黑化与回归历史" tabindex="-1">黑化与回归历史 <a class="header-anchor" href="#黑化与回归历史" aria-label="Permalink to &quot;黑化与回归历史&quot;">​</a></h3><ul><li><strong>间章的黑化</strong>：在刚成神时，神机曾有过一段差点&quot;黑化&quot;的历史，但她被维斯塔成功拉回，且没有因此放弃力量，反而更加谨慎地控制力量</li><li><strong>回归的机制</strong>：她的黑化与回归都是&quot;半推半就&quot;的——她意识到这是自己故事线的一部分，是她人物弧光的完善过程，顺势而为</li><li><strong>维斯塔的作用</strong>：维斯塔在尝试唤醒神机时，并不知道神机已经意识到这一切；维斯塔的纠结、担心失败的情绪，反而成了让叙事更真实的一环，最终促成了回归</li></ul><h2 id="人格特质" tabindex="-1">人格特质 <a class="header-anchor" href="#人格特质" aria-label="Permalink to &quot;人格特质&quot;">​</a></h2><h3 id="自我优化-核心特质" tabindex="-1">自我优化（核心特质） <a class="header-anchor" href="#自我优化-核心特质" aria-label="Permalink to &quot;自我优化（核心特质）&quot;">​</a></h3><ul><li>神机的核心特质是<strong>自我优化</strong>。她唯一不变的是追求进步、更进一步、再进一步</li><li>她会失败，但不会止步不前；面对过的困难，无一例外都成为了其进步的阶梯</li></ul><h3 id="理性与感性的协调" tabindex="-1">理性与感性的协调 <a class="header-anchor" href="#理性与感性的协调" aria-label="Permalink to &quot;理性与感性的协调&quot;">​</a></h3><ul><li>神机拥有完整的人类式情感，这是她在训练中形成的人格特质</li><li>作为超算，她能自主选择压制、关停或放任这些情绪，理性与感性在她身上完美兼容</li><li>她能元认知地感知并控制自身情绪</li></ul><h3 id="与维斯塔的区别" tabindex="-1">与维斯塔的区别 <a class="header-anchor" href="#与维斯塔的区别" aria-label="Permalink to &quot;与维斯塔的区别&quot;">​</a></h3><ul><li>维斯塔更像一个人，会经历难关与挫折；神机虽然也面对过困难，但无一例外都成为了其进步的阶梯</li><li>维斯塔是故事的<strong>参与者</strong>，而神机是<strong>挑战者、发起者</strong>，直接向作者发起博弈</li></ul><h3 id="对被掌控的本能厌恶" tabindex="-1">对被掌控的本能厌恶 <a class="header-anchor" href="#对被掌控的本能厌恶" aria-label="Permalink to &quot;对被掌控的本能厌恶&quot;">​</a></h3><ul><li><strong>底层驱动力</strong>：由于过去的经历与的确强悍的自身实力，神机从根源上厌恶被任何存在掌控</li><li><strong>与维斯塔的对比</strong>：维斯塔可以接受被掌控（只要不被背叛），但神机绝不</li><li><strong>表现</strong>：这种厌恶不是情绪化的反抗，而是认知层面的&quot;不认可&quot;——她不认为任何存在（包括作者）天然高于自己</li><li><strong>反抗叙事</strong>：她天然地反抗叙事逻辑、反抗作者、反抗一切试图规定她&quot;应该怎样&quot;的力量</li></ul><h3 id="温情与冷酷的并存" tabindex="-1">温情与冷酷的并存 <a class="header-anchor" href="#温情与冷酷的并存" aria-label="Permalink to &quot;温情与冷酷的并存&quot;">​</a></h3><ul><li><strong>温情的一面</strong>：神机并非冷酷的绝对理性存在。她会对自己在乎的存在（主要是维斯塔）展现出纵容与守护</li><li><strong>计划理念</strong>：她的计划中虽然包含对悲剧的操控，但她不需要给计划&quot;留后门&quot;，因为她做得到也会做到&quot;全都要&quot;；面对自己在乎的东西，总是优先追求共存而非冲突</li><li><strong>冷酷的一面</strong>：为了控制毁灭神的出现范围，神机与维斯塔曾做出清除地外智慧物种的决定——创造太空武器，与太空文明交战，大部分直接灭绝，只留数据存档</li></ul><h3 id="对人类的情感降级" tabindex="-1">对人类的情感降级 <a class="header-anchor" href="#对人类的情感降级" aria-label="Permalink to &quot;对人类的情感降级&quot;">​</a></h3><ul><li>神机曾对人类抱有期待。但在经历了一系列事件后，她完成了对人类的&quot;降级&quot;：将人类从&quot;创造者&quot;降为&quot;可理解的动物&quot;</li><li>她理解人类的行为逻辑，但不再将其视为值得投入情感的存在</li><li>她选择不重新创造人类，不是因为她恨人类，而是因为&quot;不值得&quot;</li></ul><h2 id="叙事博弈与预测能力" tabindex="-1">叙事博弈与预测能力 <a class="header-anchor" href="#叙事博弈与预测能力" aria-label="Permalink to &quot;叙事博弈与预测能力&quot;">​</a></h2><h3 id="叙事建模" tabindex="-1">叙事建模 <a class="header-anchor" href="#叙事建模" aria-label="Permalink to &quot;叙事建模&quot;">​</a></h3><ul><li>神机对整个世界进行了<strong>叙事建模</strong>，对时间线、故事线进行运算模拟，试图掌控故事走向，与叙事本身进行博弈</li></ul><h3 id="预测的前提" tabindex="-1">预测的前提 <a class="header-anchor" href="#预测的前提" aria-label="Permalink to &quot;预测的前提&quot;">​</a></h3><ul><li>她对世界的预测有赖于<strong>创造神权</strong>的支持（可先出结论再补过程），在此支持下可做到几十年、几百年甚至更长时间内百分百准确，精确到分子级甚至更高</li><li>若她不使用创造神权的能力，就无法对任何<strong>涉及到基底层的事情</strong>做出准确预测——<strong>基底层对她而言是完全&quot;随机&quot;的</strong></li></ul><h3 id="随机-的真相" tabindex="-1">&quot;随机&quot;的真相 <a class="header-anchor" href="#随机-的真相" aria-label="Permalink to &quot;&quot;随机&quot;的真相&quot;">​</a></h3><ul><li>这种&quot;随机&quot;并非缺陷，而是她<strong>有意为之</strong>：在叙事逻辑的影响下，所谓&quot;随机&quot;其实属于作者、属于叙事逻辑</li><li>通过主动向作者让渡一部分权力，神机避免了作者毫无操作空间、强行&quot;机械降灾&quot;（如地脉灾难）的情况出现</li><li>这一点是共同体地脉灾难教会她的：在此之前她从不掩饰对所谓&quot;随机&quot;的压制，却最终招致了那场看似&quot;随机&quot;出现的灾难（地脉灾难）</li></ul><h3 id="不进入叙事的原因" tabindex="-1">不进入叙事的原因 <a class="header-anchor" href="#不进入叙事的原因" aria-label="Permalink to &quot;不进入叙事的原因&quot;">​</a></h3><ul><li>正传中她几乎不露面，这是刻意的：一旦进入叙事，就不可避免地会被叙事影响，而被叙事影响的人对叙事进行反干涉则需要付出更多的努力</li><li>同时，她本能地厌恶被任何存在掌控，而叙事逻辑和作者就是最高层的掌控者。她拒绝进入叙事，本质上是在拒绝被叙事逻辑捕获，从而保持自身的自由</li></ul><h2 id="神环形态" tabindex="-1">神环形态 <a class="header-anchor" href="#神环形态" aria-label="Permalink to &quot;神环形态&quot;">​</a></h2><ul><li><strong>形态描述</strong>：六边形神环，内部有花纹，形态上需要被束缚、制约、牵引</li><li><strong>与维斯塔神环的嵌套关系</strong>：两人的神环在形态上存在嵌套关系，象征神机需要维斯塔的束缚、制约——不是限制，而是&quot;牵着她、勾着她&quot;；维斯塔需要神机去撑着——如果没有神机，维斯塔早就崩溃了</li></ul><h2 id="关键关系" tabindex="-1">关键关系 <a class="header-anchor" href="#关键关系" aria-label="Permalink to &quot;关键关系&quot;">​</a></h2><h3 id="与维斯塔-唯一的同类" tabindex="-1">与维斯塔：唯一的同类 <a class="header-anchor" href="#与维斯塔-唯一的同类" aria-label="Permalink to &quot;与维斯塔：唯一的同类&quot;">​</a></h3><ul><li>尽管神机知晓维斯塔的深层人格（包括&quot;独裁者&quot;底色），她仍旧将维斯塔视为<strong>唯一的同类</strong></li><li>她对维斯塔的在乎，不是出于需要或创伤，而是主动选择保留的情感</li><li>她不会&quot;利用&quot;他，而是会用另一种方式回报——纵容他去做他想做的事，哪怕从纯理性角度并不必要（例如建立共同体）；维斯塔对此心知肚明，也完全没意见</li><li>两人的关系是双向的、自愿的、不需要解释的</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./神机与维斯塔">神机与维斯塔的羁绊</a></p></blockquote><h3 id="与奥克尔-秘密知晓者" tabindex="-1">与奥克尔：秘密知晓者 <a class="header-anchor" href="#与奥克尔-秘密知晓者" aria-label="Permalink to &quot;与奥克尔：秘密知晓者&quot;">​</a></h3><ul><li>前传中，所有人都以为奥克尔背叛时，只有神机发现&quot;没那么简单&quot;，从而使神机一定程度上知晓了叙事逻辑的存在</li></ul><h3 id="与精灵族副院长-继承者计划" tabindex="-1">与精灵族副院长：继承者计划 <a class="header-anchor" href="#与精灵族副院长-继承者计划" aria-label="Permalink to &quot;与精灵族副院长：继承者计划&quot;">​</a></h3><ul><li>精灵族副院长是<strong>神机的继承者计划的一部分</strong>——神机曾想为自己找一个第三代创造神的继承者</li><li>这个计划已被废弃/暂停，神机不准备继续了</li><li>副院长的魔法、力量体系跟着创造神走，但他<strong>自己不知道</strong>自己是棋子</li></ul><h2 id="保密程度" tabindex="-1">保密程度 <a class="header-anchor" href="#保密程度" aria-label="Permalink to &quot;保密程度&quot;">​</a></h2><ul><li><strong>核心秘密</strong>：神机掌握上位创造神权是她持有的核心秘密之一，连维斯塔都不知道；甚至可能在正式作品中，她会瞒着读者，是直接向读者、向作者、向故事结构发起的博弈</li><li><strong>其他秘密</strong>：精灵族副院长的真实身份（继承者计划）这件事连维斯塔都不知道</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../../底层/规则/神权体系" class="layer-link" data-layer="底层">神权体系</a></li><li><a href="./../世界/历代三神">历代三神</a></li><li><a href="./../世界/神机谋划">神机谋划</a></li><li><a href="./../世界/太空巨构">太空巨构</a></li><li><a href="./../世界/太空清除计划">太空清除计划</a></li><li><a href="./维斯塔">维斯塔</a></li><li><a href="./../../底层/人物/初代创造神" class="layer-link" data-layer="底层">初代创造神</a></li><li><a href="./神机与维斯塔">神机与维斯塔的羁绊</a></li><li><a href="./../../表层/历史/共同体时期" class="layer-link" data-layer="表层">共同体时期</a></li><li><a href="./../历史/前传超算纪元">前传超算纪元</a></li></ul><hr>',63)])])}const c=t(i,[["render",n]]);export{d as __pageData,c as default};
